import pandas as pd
import numpy as np

input_path = '/root/environment/data/ckd_lab_data.csv'

raw = pd.read_csv(input_path)

numeric_cols = [c for c in raw.columns if c != 'patient_id']

# parse

def parse_value(value):
    if pd.isna(value):
        return np.nan
    s = str(value).strip()
    if s == '' or s.lower() in {'nan','none'}:
        return np.nan
    if 'e' in s.lower():
        try:
            return float(s)
        except ValueError:
            pass
    if ',' in s:
        s = s.replace(',', '.')
    try:
        return float(s)
    except ValueError:
        return np.nan

ranges = {
'Urine_Creatinine': (10.0,500.0),
'Phosphorus': (1.0,15.0),
}

conversion_factors = {
    'Urine_Creatinine': [0.0113, 0.113],
    'Phosphorus': [3.1],
}

# parse and drop missing
parsed = raw.copy()
for col in numeric_cols:
    parsed[col] = parsed[col].apply(parse_value)
parsed = parsed[parsed[numeric_cols].notna().all(axis=1)].reset_index(drop=True)

# convert

def convert_unit_if_needed(value, column):
    if pd.isna(value):
        return value
    min_val, max_val = ranges.get(column, (None, None))
    if min_val is None:
        return value
    if min_val <= value <= max_val:
        return value
    for factor in conversion_factors.get(column, []):
        converted = value * factor
        if min_val <= converted <= max_val:
            return converted
        if (min_val * 0.95) <= converted <= (max_val * 1.05):
            return min(max(converted, min_val), max_val)
    return value

converted = parsed.copy()
for col in ['Urine_Creatinine','Phosphorus']:
    converted[col] = converted[col].apply(lambda x: convert_unit_if_needed(x, col))

# find out-of-range after conversion
for col,(mn,mx) in ranges.items():
    s = converted[col]
    mask = (s < mn) | (s > mx)
    print(col, 'out count', mask.sum())
    print('values', s[mask].head(10).tolist())
